#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cctype>

using namespace std;

typedef pair<int,int> pii;

int n, t;
char nau[10][10], pom[10][10];  // fixed size as original
int odl[10][10];
bool moge[60][10][10][10][10];

int dx[5] = {-1, 0, 1, 0, 0};
int dy[5] = {0, 1, 0, -1, 0};

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin >> n >> t;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> nau[i][j];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> pom[i][j];

    // init odl
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            odl[i][j] = 1000;

    // find start
    int sx, sy;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (nau[i][j] == 'Z') { sx = i; sy = j; }

    // BFS
    queue<pii> Q;
    odl[sx][sy] = 0;
    Q.push({sx, sy});
    while (!Q.empty()) {
        int x = Q.front().first, y = Q.front().second;
        Q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (inside(nx, ny) && isdigit(nau[nx][ny]) && odl[nx][ny] == 1000) {
                odl[nx][ny] = odl[x][y] + 1;
                Q.push({nx, ny});
            }
        }
    }

    // init moge
    for (int k = 0; k < 60; ++k)
        for (int i = 0; i < 10; ++i)
            for (int j = 0; j < 10; ++j)
                for (int l = 0; l < 10; ++l)
                    for (int m = 0; m < 10; ++m)
                        moge[k][i][j][l][m] = false;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            for (int d = 0; d < 5; ++d) {
                int ni = i + dx[d], nj = j + dy[d];
                if (inside(ni, nj) && isdigit(nau[i][j]) && isdigit(nau[ni][nj]))
                    moge[0][i][j][ni][nj] = true;
            }

    for (int k = 0; k <= t - 2; ++k)
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int l = 0; l < n; ++l)
                    for (int m = 0; m < n; ++m) {
                        if (!moge[k][i][j][l][m]) continue;
                        for (int d = 0; d < 5; ++d) {
                            int nl = l + dx[d], nm = m + dy[d];
                            if (inside(nl, nm) && isdigit(nau[nl][nm]) && odl[l][m] >= k+2 && odl[nl][nm] >= k+2)
                                moge[k+1][i][j][nl][nm] = true;
                        }
                    }

    // collect digits
    vector<pii> a;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(nau[i][j]))
                a.push_back({i, j});

    int V = 2 * (int)a.size() + 2;
    vector<vector<pii>> G(V); // (to, capacity)

    // source/sink edges
    for (int i = 0; i < (int)a.size(); ++i) {
        int cap1 = nau[a[i].first][a[i].second] - '0';
        G[0].push_back({i+1, cap1});
        G[i+1].push_back({0, 0});
        int cap2 = pom[a[i].first][a[i].second] - '0';
        G[a.size()+1+i].push_back({V-1, cap2});
        G[V-1].push_back({a.size()+1+i, 0});
    }

    // middle edges
    for (int i = 0; i < (int)a.size(); ++i)
        for (int j = 0; j < (int)a.size(); ++j) {
            bool reach = false;
            for (int k = 0; k <= t-1; ++k)
                if (moge[k][a[i].first][a[i].second][a[j].first][a[j].second]) {
                    reach = true;
                    break;
                }
            if (reach) {
                G[i+1].push_back({a.size()+1+j, 1000});
                G[a.size()+1+j].push_back({i+1, 0});
            }
        }

    // max flow
    int flow = 0;
    while (true) {
        vector<bool> vis(V, false);
        vector<int> par(V, -1);
        queue<int> q;
        vis[0] = true;
        q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : G[u])
                if (!vis[e.first] && e.second > 0) {
                    vis[e.first] = true;
                    par[e.first] = u;
                    q.push(e.first);
                }
        }
        if (par[V-1] == -1) break;

        int add = 1000;
        for (int v = V-1; v != 0; v = par[v]) {
            int u = par[v];
            for (auto& e : G[u])
                if (e.first == v) add = min(add, e.second);
        }

        for (int v = V-1; v != 0; v = par[v]) {
            int u = par[v];
            for (auto& e : G[u])
                if (e.first == v) e.second -= add;
            for (auto& e : G[v])
                if (e.first == u) e.second += add;
        }
        flow += add;
    }

    cout << flow;
    return 0;
}
